def is_sum_free(subset):
    for i in range(len(subset)):
        for j in range(i, len(subset)):
            if subset[i] + subset[j] in subset:
                return False
    return True

def find_partition(n, k):
    # Try to partition {1, ..., n} into k sum-free sets
    # This is a backtracking problem.
    # To make it faster, we can assign numbers one by one.
    sets = [[] for _ in range(k)]

    def backtrack(current_num):
        if current_num > n:
            return True

        for i in range(k):
            sets[i].append(current_num)
            if is_sum_free(sets[i]):
                if backtrack(current_num + 1):
                    return True
            sets[i].pop()
        return False

    if backtrack(1):
        return sets
    return None

# Since 40 is too large for simple backtracking,
# let's try to find a partition of a smaller n first.
for n in range(1, 15):
    res = find_partition(n, 3)
    if res is None:
        print(f"f({n}) > 3")
        break
    else:
        print(f"f({n}) <= 3")

def backtrack_fast(n, k, sets, curr):
    if curr > n:
        return True

    for i in range(k):
        # Check if adding curr to sets[i] keeps it sum-free
        is_possible = True
        for j in range(len(sets[i])):
            for l in range(j, len(sets[i])):
                if sets[i][j] + sets[i][l] == curr:
                    is_possible = False
                    break
            if not is_possible:
                break

        if is_possible:
            sets[i].append(curr)
            if backtrack_fast(n, k, sets, curr + 1):
                return True
            sets[i].pop()
    return False

